  if (isPhotoChannelView(view, params)) return fast ? FAST_PHOTO_CHANNEL_LIMIT : PHOTO_CHANNEL_LIMIT;
  if (view === "channel") return fast ? FAST_CHANNEL_LIMIT : 36;
